if($entity!==''){$sql.=' AND entity_type=?';$types.='s';$params[]=$entity;}if($user!==''){$sql.=' AND username LIKE ?';$types.='s';$params[]='%'.$user.'%';}$sql.=' ORDER BY id DESC LIMIT 500';$stmt=$conn->prepare($sql);if($types)$stmt->bind_param($types,...$params);$stmt->execute();$logs=$stmt->get_result();$entities=$conn->query('SELECT DISTINCT entity_type FROM audit_logs ORDER BY entity_type');
