<div class="page-hero"><div><div class="page-kicker">Security</div><h1 class="page-title">Audit log</h1><p class="page-subtitle">See who created, changed, deleted, converted or reset important records.</p></div></div>
<form class="card card-body mb-3" method="get"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="user" value="<?=htmlspecialchars($user);?>" placeholder="Search username"></div><div class="col-md-4"><select class="form-select" name="entity"><option value="">All record types</option><?php while($e=$entities->fetch_assoc()):?><option value="<?=htmlspecialchars($e['entity_type']);?>" <?=$entity===$e['entity_type']?'selected':'';?>><?=htmlspecialchars(ucwords(str_replace('_',' ',$e['entity_type'])));?></option><?php endwhile;?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Filter</button></div></div></form>
<div class="card"><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody><?php if(!$logs->num_rows):?><tr><td colspan="5"><div class="empty-state">No activity has been recorded yet.</div></td></tr><?php endif;?><?php while($log=$logs->fetch_assoc()):?><tr><td><?=date('d M Y H:i',strtotime($log['created_at']));?></td><td><?=htmlspecialchars($log['username']?:'System');?></td><td><span class="badge text-bg-secondary"><?=htmlspecialchars($log['action']);?></span></td><td><?=htmlspecialchars(ucwords(str_replace('_',' ',$log['entity_type'])));?><?php if($log['entity_id']!==null):?><small class="d-block text-muted">#<?=htmlspecialchars($log['entity_id']);?></small><?php endif;?></td><td><?=htmlspecialchars($log['summary']);?></td></tr><?php endwhile;?></tbody></table></div></div>
